import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Arrays;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();if (s == null) return;int n = s.length();long[][] dist = new long[26][26];for (int i = 0; i < 26; i++) {Arrays.fill(dist[i], 1000000000000L);dist[i][i] = 0;}String mStr = br.readLine();if (mStr == null) return;int m = Integer.parseInt(mStr.trim());for (int i = 0; i < m; i++) {String[] parts = br.readLine().split(" ");int u = parts[0].charAt(0) - 'a';int v = parts[1].charAt(0) - 'a';long cost = Long.parseLong(parts[2]);if (cost < dist[u][v]) {dist[u][v] = cost;dist[v][u] = cost;}}for (int k = 0; k < 26; k++) {for (int i = 0; i < 26; i++) {for (int j = 0; j < 26; j++) {if (dist[i][k] + dist[k][j] < dist[i][j]) {dist[i][j] = dist[i][k] + dist[k][j];}}}}long totalCost = 0;for (int i = 0; i < n / 2; i++) {int c1 = s.charAt(i) - 'a';int c2 = s.charAt(n - 1 - i) - 'a';if (c1 != c2) {long minPairCost = 1000000000000L;for (int k = 0; k < 26; k++) {long current = dist[c1][k] + dist[c2][k];if (current < minPairCost) {minPairCost = current;}}totalCost += minPairCost;}}System.out.println(totalCost);}}